using System; using System.IO; using System.Security.Cryptography; using System.Management; using System.Text; using System.Text.Json; public class LicensePayload { public string MachineId { get; set; } public DateTime? ExpirationDate { get; set; } } class Program { static void Main() { string mId = GetP(); string payloadJson = JsonSerializer.Serialize(new LicensePayload { MachineId = mId, ExpirationDate = DateTime.UtcNow.AddYears(10) }); byte[] pBytes = Encoding.UTF8.GetBytes(payloadJson); using var rsa = RSA.Create(); rsa.ImportRSAPrivateKey(Convert.FromBase64String(""), out _); byte[] sig = rsa.SignData(pBytes, HashAlgorithmName.SHA256, RSASignaturePadding.Pkcs1); string final = Convert.ToBase64String(pBytes) + "." + Convert.ToBase64String(sig); Console.WriteLine(final); File.WriteAllText(@"..\src\StockFlowPro.API\license.key", final); } static string GetP() { string cpu = G("Win32_Processor", "ProcessorId"); string bios = G("Win32_BIOS", "SerialNumber"); string board = G("Win32_BaseBoard", "SerialNumber"); string raw = cpu + "|" + bios + "|" + board; using var sha = SHA256.Create(); var hash = sha.ComputeHash(Encoding.UTF8.GetBytes(raw)); string b64 = Convert.ToBase64String(hash).Replace("+","").Replace("/","").Replace("=","").ToUpper(); if(b64.Length>16)b64=b64.Substring(0,16); return "MACH-"+b64.Substring(0,4)+"-"+b64.Substring(4,4)+"-"+b64.Substring(8,4)+"-"+b64.Substring(12,4); } static string G(string c, string p) { try { using var s = new ManagementObjectSearcher("SELECT " + p + " FROM " + c); foreach (ManagementObject o in s.Get()) { return o[p]?.ToString()?.Trim() ?? ""; } } catch {} return ""; } }
